namespace sv_076058b5823d488cb996925dfa6b0f95.Client.Models;

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public required DateTimeOffset EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> StatusUpdates { get; init; }
}

public sealed class StatusUpdate
{
    public required string Description { get; init; }
    public required DateTimeOffset Timestamp { get; init; }
}

using sv_076058b5823d488cb996925dfa6b0f95.Client.Models;

namespace sv_076058b5823d488cb996925dfa6b0f95.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_076058b5823d488cb996925dfa6b0f95.Client.Models;
using sv_076058b5823d488cb996925dfa6b0f95.Client.Services;

namespace sv_076058b5823d488cb996925dfa6b0f95.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment
        {
            TrackingNumber = "TRK-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 20, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Timestamp = new DateTimeOffset(2026, 6, 14, 9, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Arrived at sorting facility", Timestamp = new DateTimeOffset(2026, 6, 15, 3, 30, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Departed sorting facility", Timestamp = new DateTimeOffset(2026, 6, 16, 8, 0, 0, TimeSpan.Zero) },
            ]
        },
        ["TRK-002"] = new Shipment
        {
            TrackingNumber = "TRK-002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 15, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Timestamp = new DateTimeOffset(2026, 6, 12, 10, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "In transit", Timestamp = new DateTimeOffset(2026, 6, 13, 6, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Out for delivery", Timestamp = new DateTimeOffset(2026, 6, 15, 7, 30, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Delivered", Timestamp = new DateTimeOffset(2026, 6, 15, 11, 45, 0, TimeSpan.Zero) },
            ]
        },
        ["TRK-003"] = new Shipment
        {
            TrackingNumber = "TRK-003",
            Status = "Processing",
            Location = "Los Angeles, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 22, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Order placed", Timestamp = new DateTimeOffset(2026, 6, 16, 14, 0, 0, TimeSpan.Zero) },
                new StatusUpdate { Description = "Label created", Timestamp = new DateTimeOffset(2026, 6, 16, 16, 30, 0, TimeSpan.Zero) },
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_076058b5823d488cb996925dfa6b0f95.Client.Models;

namespace sv_076058b5823d488cb996925dfa6b0f95.Client.Services;

/// <summary>
/// HTTP-based implementation used when running on WebAssembly.
/// </summary>
public sealed class ShipmentServiceClient(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_076058b5823d488cb996925dfa6b0f95.Client.Models
@using sv_076058b5823d488cb996925dfa6b0f95.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment <strong>@TrackingNumber</strong>…</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>Shipment <strong>@TrackingNumber</strong> was not found.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.StatusUpdates)
            {
                <li>
                    <time datetime="@update.Timestamp.ToString("o")">@update.Timestamp.ToString("g")</time>
                    &mdash; @update.Description
                </li>
            }
        </ul>
    </div>
}

@code {
    private CancellationTokenSource? _cts;
    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    protected override Task OnParametersSetAsync()
    {
        // Cancel any in-flight request when the route parameter changes.
        CancelPending();
        return LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        _loading = true;
        _errorMessage = null;
        _shipment = null;

        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation away or disposal — silently abandon.
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (HttpRequestException ex)
        {
            Logger.LogError(ex, "Network error fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "A network error occurred. Please check your connection and try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Unexpected error fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    private void CancelPending()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

